DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[TransactionHistory]([TransactionID],[ProductID],[ReferenceOrderID],[ReferenceOrderLineID],[TransactionDate],[TransactionType],[Quantity],[ActualCost],[ModifiedDate],LoadBatchID) SELECT S.[TransactionID],S.[ProductID],S.[ReferenceOrderID],S.[ReferenceOrderLineID],S.[TransactionDate],S.[TransactionType],S.[Quantity],S.[ActualCost],S.[ModifiedDate],@B FROM ssis_flow.Delta_TransactionHistory S;
INSERT stg.[TransactionHistory]([TransactionID],[ProductID],[ReferenceOrderID],[ReferenceOrderLineID],[TransactionDate],[TransactionType],[Quantity],[ActualCost],[ModifiedDate],LoadBatchID) SELECT [TransactionID],[ProductID],[ReferenceOrderID],[ReferenceOrderLineID],[TransactionDate],[TransactionType],[Quantity],[ActualCost],[ModifiedDate],@B FROM etl_raw.[TransactionHistory];
INSERT etl_v2.SourceChange SELECT @B,N'Production.TransactionHistory','I',@Next,(SELECT R.[TransactionID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[TransactionHistory] R;
END ELSE BEGIN
SELECT [TransactionID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_TransactionHistory FROM ssis_flow.Delta_TransactionHistory;
INSERT etl_v2.SourceChange SELECT @B,N'Production.TransactionHistory',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[TransactionID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_TransactionHistory C LEFT JOIN etl_raw.[TransactionHistory] R ON R.[TransactionID]=C.[TransactionID];
DELETE R FROM etl_raw.[TransactionHistory] R JOIN #CT_TransactionHistory C ON R.[TransactionID]=C.[TransactionID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[ProductID]=S.[ProductID],R.[ReferenceOrderID]=S.[ReferenceOrderID],R.[ReferenceOrderLineID]=S.[ReferenceOrderLineID],R.[TransactionDate]=S.[TransactionDate],R.[TransactionType]=S.[TransactionType],R.[Quantity]=S.[Quantity],R.[ActualCost]=S.[ActualCost],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[TransactionHistory] R JOIN #CT_TransactionHistory C ON R.[TransactionID]=C.[TransactionID] JOIN ssis_flow.Delta_TransactionHistory S ON S.[TransactionID]=C.[TransactionID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[TransactionHistory]([TransactionID],[ProductID],[ReferenceOrderID],[ReferenceOrderLineID],[TransactionDate],[TransactionType],[Quantity],[ActualCost],[ModifiedDate],LoadBatchID) SELECT S.[TransactionID],S.[ProductID],S.[ReferenceOrderID],S.[ReferenceOrderLineID],S.[TransactionDate],S.[TransactionType],S.[Quantity],S.[ActualCost],S.[ModifiedDate],@B FROM #CT_TransactionHistory C JOIN ssis_flow.Delta_TransactionHistory S ON S.[TransactionID]=C.[TransactionID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[TransactionHistory] R WHERE R.[TransactionID]=S.[TransactionID]);
INSERT stg.[TransactionHistory]([TransactionID],[ProductID],[ReferenceOrderID],[ReferenceOrderLineID],[TransactionDate],[TransactionType],[Quantity],[ActualCost],[ModifiedDate],LoadBatchID) SELECT R.[TransactionID],R.[ProductID],R.[ReferenceOrderID],R.[ReferenceOrderLineID],R.[TransactionDate],R.[TransactionType],R.[Quantity],R.[ActualCost],R.[ModifiedDate],@B FROM etl_raw.[TransactionHistory] R JOIN #CT_TransactionHistory C ON R.[TransactionID]=C.[TransactionID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;